<title>Slooin Yol Açılışı</title>
<link rel="preconnect" href="https://fonts.googleapis.com" />
<link href="https://fonts.googleapis.com/css2?family=Instrument+Sans:wght@400;500;600;700&display=swap" rel="stylesheet" />
<style>
  /* Karsilama ekrani acilis animasyonu - WEB PROTOTIPI.
     Referans: kullanicinin 2026-09-16 tarihli ekran kaydi (simge S kivrimli
     yolda ilerler, gectigi iz renklenir, donemeclerde baslik+altyazi
     belirir, sonda simge ortaya oturur ve buton gelir).
     Kullanicinin duzeltmeleri (2026-09-20): daha yavas, her donemecte
     kisa duraklama, etiketler cizginin sag/solunda ve uzak, baslangic
     referans gibi (simge tek basina -> yol belirir, iz asagiya uzar).
     Slooin uyarlamasi: iz TURUNCU (canlilik), simge uygulama simgesi,
     dort donemec = karsilamanin dort tanitim karti.
     Matematik (cubic Bezier ornekleme + uzunluk tablosu) RN'e 1:1 tasinir. */
  :root {
    --zemin: #FAF7F3; --metin: #17130F; --ikincil: #6E6660; --soluk: #A39B93;
    --cizgi: #E2DAD2; --turuncu: #FE7813; --turuncu-basili: #E06509; --beyaz: #fff;
    --govde: 'Instrument Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;
    /* Emil Kowalski easing seti: giris/cikis ease-out, ekranda hareket
       ease-in-out, yerine oturma iOS cekmece egrisi. Yerlesik CSS
       egrileri zayif kalir. */
    --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
    --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
    --ease-otur: cubic-bezier(0.32, 0.72, 0, 1);
  }
  @media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) { --zemin: #FAF7F3; } }
  * { box-sizing: border-box; }
  body { margin: 0; background: #2A2521; font-family: var(--govde); color: var(--metin); min-height: 100%; display: grid; place-items: center; padding: 24px 16px; }
  .cihaz { width: min(390px, 100%); height: 844px; max-height: calc(100vh - 48px); background: var(--zemin); border-radius: 44px; overflow: hidden; position: relative; box-shadow: 0 40px 80px -30px rgba(0,0,0,.7), inset 0 0 0 10px #16151a; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  .ekran { position: absolute; inset: 10px; border-radius: 36px; overflow: hidden; background: var(--zemin); }

  /* dunya: kamera bunu kaydirir */
  .dunya { position: absolute; left: 0; top: 0; width: 100%; will-change: transform; }
  .dunya svg { display: block; width: 100%; height: auto; }
  /* Simge YALNIZCA transform ile hareket eder (left/top layout tetikler). */
  .simge { position: absolute; left: 0; top: 0; width: 62px; height: 62px; border-radius: 16px; box-shadow: 0 14px 28px -12px rgba(23,19,15,.45); will-change: transform; transform-origin: center; }
  .simge img { width: 100%; height: 100%; display: block; border-radius: 16px; }
  /* Etiket girisi: ease-out, %97 olcek + 6 px + 2 px blur -> net. Cikis daha kisa.
     transform-origin yola donuk: soldaki etiket sag kenarindan, sagdaki sol
     kenarindan buyur. */
  .etiket { position: absolute; opacity: 0; transform: translate3d(0, 6px, 0) scale(.97); filter: blur(2px); transition: opacity .2s var(--ease-out), transform .2s var(--ease-out), filter .2s var(--ease-out); }
  .etiket.sol { transform-origin: right center; } .etiket.sag { transform-origin: left center; }
  .etiket i { display: block; font-style: normal; font-size: 11px; letter-spacing: .08em; color: var(--soluk); font-weight: 600; margin-bottom: 4px; font-variant-numeric: tabular-nums; }
  .etiket.acik { opacity: 1; transform: none; filter: blur(0); transition-duration: .3s; }
  .etiket b { display: block; font-size: 19px; letter-spacing: -.3px; line-height: 1.15; }
  .etiket span { display: block; font-size: 13px; color: var(--ikincil); margin-top: 3px; line-height: 1.3; }
  .etiket.sag { text-align: left; }
  .etiket.sol { text-align: right; }

  /* son durum */
  .son { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 24px; pointer-events: none; }
  .son.acik { pointer-events: auto; }
  /* Son durumun ogeleri 60 ms arayla, her biri 300 ms ease-out (stagger 30-80 ms bandi). */
  .son .g { opacity: 0; transform: translate3d(0, 8px, 0) scale(.97); filter: blur(2px); transition: opacity .3s var(--ease-out), transform .3s var(--ease-out), filter .3s var(--ease-out); }
  .son.acik .g { opacity: 1; transform: none; filter: blur(0); }
  .son.acik .g:nth-child(2) { transition-delay: .06s } .son.acik .g:nth-child(3) { transition-delay: .12s } .son.acik .g:nth-child(4) { transition-delay: .18s } .son.acik .g:nth-child(5) { transition-delay: .24s }
  .son .yer { height: 78px; }
  .son img.marka { width: 148px; margin-top: 22px; }
  .son h1 { font-size: 22px; letter-spacing: -.4px; margin: 10px 0 0; font-weight: 700; }
  .son h1 em { font-style: normal; color: var(--turuncu); }
  .son .eylem { margin-top: 34px; display: inline-flex; align-items: center; gap: 10px; background: var(--turuncu); color: #fff; font-weight: 600; font-size: 16px; padding: 16px 28px; border-radius: 999px; box-shadow: 0 14px 30px -14px rgba(254,120,19,.7); text-decoration: none; }
  .son .eylem:active { transform: scale(.98); transition: transform .12s var(--ease-out); }
  .son .ikincil { margin-top: 18px; font-size: 14px; color: var(--ikincil); }
  .son .ikincil b { color: var(--metin); font-weight: 600; }
  .atif { position: absolute; left: 0; right: 0; bottom: 18px; text-align: center; font-size: 10px; color: var(--soluk); }
  .atla { position: absolute; right: 22px; top: 22px; font-size: 13px; color: var(--ikincil); background: rgba(255,255,255,.7); padding: 6px 12px; border-radius: 999px; z-index: 5; }
  .atla { transition: opacity .2s var(--ease-out); }
  .atla.gizli { opacity: 0; pointer-events: none; }
  .yeniden { position: fixed; left: 50%; bottom: 14px; transform: translateX(-50%); font-size: 13px; color: #CFC6BD; background: rgba(255,255,255,.08); padding: 8px 14px; border-radius: 999px; border: 0; cursor: pointer; font-family: inherit; }
  /* Hareketi azalt: sifir animasyon DEGIL - yer degistirme ve blur kalkar, solma kalir. */
  @media (prefers-reduced-motion: reduce) { .etiket, .son .g { transform: none !important; filter: none !important; transition: opacity .2s ease !important; } }
</style>

<div class="cihaz" id="cihaz" role="button" aria-label="Animasyonu atla">
  <div class="ekran">
    <div class="atla" id="atla">Atla</div>
    <div class="dunya" id="dunya">
      <svg id="yol" viewBox="0 0 390 2200" aria-hidden="true">
        <path id="yolGri" fill="none" stroke="#E2DAD2" stroke-width="1.6" />
        <path id="yolTuruncu" fill="none" stroke="#FE7813" stroke-width="3.2" stroke-linecap="round" />
