  .son.acik .g { opacity: 1; transform: none; filter: blur(0); }
  .son.acik .g:nth-child(2) { transition-delay: .06s } .son.acik .g:nth-child(3) { transition-delay: .12s } .son.acik .g:nth-child(4) { transition-delay: .18s } .son.acik .g:nth-child(5) { transition-delay: .24s }
  .son .yer { height: 78px; }
  .son img.marka { width: 148px; margin-top: 22px; }
