30	  .secenek p { margin: 0; font-size: 13px; color: var(--tahta-soluk); line-height: 1.45; }
31	  .yeniden { font: inherit; font-size: 12px; color: var(--tahta-metin); background: transparent; border: 1px solid var(--tahta-cizgi); border-radius: 999px; padding: 5px 11px; cursor: pointer; white-space: nowrap; }
32	  .yeniden:hover { border-color: var(--tahta-soluk); }
33	  .yeniden:focus-visible { outline: 2px solid var(--turuncu); outline-offset: 2px; }
34	
35	  /* telefon */
36	  .cihaz { width: 100%; aspect-ratio: 390 / 780; max-width: 100%; background: var(--zemin); border-radius: 40px; overflow: hidden; position: relative; box-shadow: 0 30px 60px -28px rgba(0,0,0,.8), inset 0 0 0 8px #16151a; }
37	  .ekran { position: absolute; inset: 8px; border-radius: 33px; overflow: hidden; background: var(--zemin); font-family: var(--govde); color: var(--metin); container-type: inline-size; }
