  fotografUriRef.current = fotografUri
  const kaynakAcikRef = useRef(kaynakAcik)
  kaynakAcikRef.current = kaynakAcik

  useEffect(() => {
    let gecerli = true
    aktifCheckInimiGetir()
      .then((c) => {
        if (gecerli && c) setMekan({ id: c.mekanId, ad: c.mekanAdi })
